package au.com.roningroup.patrollink;
import android.app.*;import android.content.*;import android.webkit.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class)
public final class SilverTrackCaptureTest {
 Instrumentation ins;Activity activity;WebView web;
 @Before public void setup(){ins=InstrumentationRegistry.getInstrumentation();activity=ins.startActivitySync(new Intent(ins.getTargetContext(),MonitorFilterHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.runOnMainSync(()->{web=new WebView(activity);web.getSettings().setJavaScriptEnabled(true);activity.setContentView(web);});}
 @After public void end(){ins.runOnMainSync(()->{web.destroy();activity.finish();});}
 String js(String script)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> data=new AtomicReference<>();ins.runOnMainSync(()->web.evaluateJavascript(script,x->{data.set(x);latch.countDown();}));assertTrue(latch.await(10,TimeUnit.SECONDS));return String.valueOf(new JSONTokener(data.get()).nextValue());}
 void html(String body)throws Exception{ins.runOnMainSync(()->web.loadDataWithBaseURL(PatrolEngine.MONITOR,"<html><body>"+body+"<span id='done'>fixture</span></body></html>","text/html","UTF-8",PatrolEngine.MONITOR));for(int i=0;i<80;i++){if("true".equals(js("!!document.getElementById('done')")))return;Thread.sleep(100);}fail("Fixture load");}
 JSONObject row(String id)throws Exception{return new JSONObject().put("id",id).put("guard","Synthetic Guard").put("property","Synthetic Property").put("issue","Parking Breach - 1st Warning").put("date","14/07/2026 06:00");}
 String cells(String id,String link){return "<td>"+id+"</td><td>Synthetic Property</td><td>Parking Breach - 1st Warning</td><td>14/07/2026 06:00</td><td>Synthetic Guard</td><td>"+link+"</td>";}
 JSONArray links(JSONArray rows)throws Exception{return new JSONArray(js("JSON.stringify("+VehicleCaptureScripts.LINKS+"("+rows+"))"));}
 @Test public void NestedTablesResolveTheInnerReportRow()throws Exception{html("<table><tr><td><table><tr>"+cells("2000001","<a href='IssueDetails.aspx?IssueID=2000001'>View</a>")+"</tr></table></td></tr></table>");JSONArray out=links(new JSONArray().put(row("2000001")));assertEquals(1,out.length());assertEquals("/admincustomer/issues/issuedetails.aspx:issueid=2000001",out.getJSONObject(0).getString("identity"));}
 @Test public void SameMinuteReportsUseTheirStableIssueIds()throws Exception{html("<table><tr>"+cells("2000001","<a href='IssueDetails.aspx?IssueID=2000001'>View</a>")+"</tr><tr>"+cells("2000002","<a href='IssueDetails.aspx?IssueID=2000002'>View</a>")+"</tr></table>");assertEquals(2,links(new JSONArray().put(row("2000001")).put(row("2000002"))).length());}
 @Test public void DivRowsAndLiteralJavascriptReportFunctionsAreReadWithoutExecutingThem()throws Exception{html("<script>window.viewReport=function(issueID){window.open('IssueDetails.aspx?IssueID='+issueID);window.executed=true;};</script><div class='issue-row'><span>2000001</span><span>Synthetic Property</span><span>Parking Breach - 1st Warning</span><span>14/07/2026 06:00</span><span>Synthetic Guard</span><a href='javascript:viewReport(2000001)'>View</a></div>");assertEquals(1,links(new JSONArray().put(row("2000001"))).length());assertEquals("undefined",js("typeof window.executed"));}
 @Test public void HiddenPasswordsAndSameOriginFramesYieldLabelledFieldsAndTrueDate()throws Exception{
  html("<input type='password' style='display:none'><iframe srcdoc=\"<label for='plate'>Registration No.</label><input id='plate' value='ABC123'><table><tr><td>Colour</td><td>Black</td></tr><tr><td>Reported Date</td><td>14/07/2026 06:00</td></tr></table>\"></iframe>");
  Thread.sleep(300);JSONObject result=new JSONObject(js("JSON.stringify("+VehicleCaptureScripts.FIELDS+"())"));assertFalse(result.optBoolean("login"));assertEquals("ABC123",result.getJSONObject("vehicle").getString("plate"));assertEquals("14/07/2026 06:00",result.getString("reportedDate"));
  html("<label>Sign in</label><input type='password'><input name='username'>");assertTrue(new JSONObject(js("JSON.stringify("+VehicleCaptureScripts.FIELDS+"())")).getBoolean("login"));
 }
 @Test public void CredentialAndMutatingLinksCannotBeCaptured()throws Exception{html("<table><tr>"+cells("2000001","<a href='IssueDetails.aspx?IssueID=2000001&amp;action=view&amp;action=delete'>View</a><a href='EditIssue.aspx?IssueID=2000001'>Edit</a><a href='https://user:secret@trlsecurity.silvertracker.net/AdminCustomer/Issues/IssueDetails.aspx?IssueID=2000001'>Unsafe</a>")+"</tr></table>");assertEquals(0,links(new JSONArray().put(row("2000001"))).length());}
 @Test public void ExplicitCaptureExplainsMissingPublisherPairingWithoutUsingHistoryScanGate()throws Exception{html("<h1>ISSUE MONITOR</h1>");ins.runOnMainSync(()->{FleetRelay.configure(activity,true,1);assertFalse(MasterFeedClient.ready(activity,true));SilverTrackVehicleCollector.captureLoadedPage(activity,web,java.time.ZoneId.of("Australia/Brisbane"));});assertTrue(activity.getSharedPreferences("patrol_master_feed_v1",0).getString("vehicle_scan_status","").contains("Publisher"));assertFalse(SilverTrackVehicleCollector.status(activity).contains("created: 1"));}
}
